    // Invert so 1.0 is the sharp front, fading to 0.0
    radarPulse = 1.0 - radarPulse;
    
    // Shape the pulse: slightly sharper front, long fade
    radarPulse = pow(radarPulse, 5.0); 

    // Secondary interference wave for "echo" texture
